test('sample decision respects budget and deadline and refuses an unfulfillable approval', () => {
  const first = sampleProposal(150, 180000);
  assert.deepEqual(first.options.map(option => option.totalCents), [165000, 195000, 175000]);
  assert.equal(first.options[0].withinBudget, true);
  assert.equal(first.options[0].onTime, false);
  assert.equal(first.chosen?.id, 'split');
  const impossible = reviewSample(initialRehearsal(), 150, 100000);
  assert.equal(impossible.proposal?.chosen, null);
  assert.throws(() => approveSample(impossible), /feasible reviewed proposal/);
  assert.throws(() => sampleProposal(150.5, 180000));
  assert.throws(() => sampleProposal(201, 180000));
  assert.throws(() => sampleProposal(150, NaN));
});

test('changing a sample preserves prior context but cannot reuse its approval for a new quantity', () => {
  let state = reviewSample(initialRehearsal(), 150, 180000);
  state = approveSample(state);
  assert.equal(state.approved?.quantity, 150);
  const next = replaySample(state);
  assert.equal(next.proposal?.chosen?.totalCents, 163000);
  assert.equal(next.proposal?.quantity, 140);
  assert.equal(next.approved, null);
  assert.equal(next.memory[0].quantity, 150);
  assert.equal(state.approved?.quantity, 150);
  const edited = invalidateSample(state);
  assert.equal(edited.proposal, null);
  assert.equal(edited.approved, null);
  assert.throws(() => approveSample(edited));
  assert.throws(() => replaySample(initialRehearsal()));
});

test('a cloud-verified proposal cannot approve a changed order, policy, price or result',async()=>{
  const company=validateCompany(JSON.parse(await readFile('fixtures/company.json','utf8')));
  let state=applyIntent(newConversation('cloud-approved'),{action:'review',quantity:150},'150 shirts',company).state;
  state.cloudReview={fingerprint:reviewFingerprint(state,company),receiptId:'verified-receipt'};
  assert.equal(hasCurrentCloudReview(state,company),true);
  const approved=applyIntent(state,{action:'approve'},'Yes approve it',company).state;
  assert.equal(hasCurrentCloudReview(approved,company),true);
  assert.equal(hasCurrentCloudReview({...state,quantity:140},company),false);
  assert.equal(hasCurrentCloudReview({...state,notes:['Never split shipments.']},company),false);
  assert.equal(hasCurrentCloudReview(state,{...company,stock:{...company.stock,unitCents:901}}),false);
  const altered=structuredClone(state);altered.rehearsal.proposal!.chosen!.totalCents=1;
  assert.equal(hasCurrentCloudReview(altered,company),false);
  const noted=applyIntent(approved,{action:'remember',memoryNote:'Never split shipments.'},'Never split shipments.',company).state;
  assert.equal(noted.rehearsal.proposal,null);assert.equal(noted.rehearsal.approved,null);
  assert.equal(hasCurrentCloudReview(noted,company),false);
  assert.equal(applyIntent(noted,{action:'approve'},'Yes approve',company).state.rehearsal.approved,null);
  assert.equal(applyIntent(noted,{action:'draft'},'Write the packet',company).draft,null);
});

test('conversation approval is explicit and amendments cannot inherit it',()=>{
  let state=applyIntent(newConversation('test'),{action:'review',quantity:150},'150 shirts').state;
  for(const message of ['Do not approve','Can I approve?','No','hold it'])assert.equal(applyIntent(state,{action:'approve'},message).state.rehearsal.approved,null);
  state=applyIntent(state,{action:'approve'},'Yes, approve it').state;
  assert.equal(state.rehearsal.approved?.totalCents,175000);
  const amended=applyIntent(state,{action:'draft',quantity:140},'Draft it for 140 shirts');
  assert.equal(amended.state.rehearsal.proposal?.chosen?.totalCents,163000);
  assert.equal(amended.state.rehearsal.approved,null);assert.equal(amended.draft,null);
});

test('preparing or publishing a changed order cannot silently use the old approval',()=>{
  let state=applyIntent(newConversation('publish'),{action:'review',quantity:140},'140 shirts').state;
  state=applyIntent(state,{action:'approve'},'Approve').state;
  for(const action of ['launch','publish'] as const){
    assert.throws(()=>applyIntent(state,{action,quantity:150},'Publish the work ticket for 150 shirts'),/Review and approve/);
    assert.throws(()=>applyIntent(state,{action,budgetDollars:2000},'Prepare a launch with budget 2000'),/Review and approve/);
  }
  assert.equal(state.rehearsal.approved?.quantity,140);
});

test('a saved packet belongs to its exact approval, even when a later order has the same quantity',()=>{
  let state=applyIntent(newConversation('packets'),{action:'review',quantity:150},'150 shirts').state;state.revision=1;
  state=applyIntent(state,{action:'approve'},'Approve').state;state.revision=2;
  const packet={id:'saved',name:'Approved work packet · 150 shirts',url:'/packet',approvalRevision:state.approvalRevision!,approval:{...state.rehearsal.approved!}};
  assert.equal(isCurrentPacket(state,packet),true);
  assert.equal(isCurrentPacket(state,{id:'legacy',name:packet.name,url:packet.url}),false);
  const noted=applyIntent(state,{action:'remember',memoryNote:'Never split shipments.'},'Never split shipments').state;noted.revision=3;
  state=applyIntent(noted,{action:'review',budgetDollars:2000},'Budget 2000 dollars').state;state.revision=4;
  state=applyIntent(state,{action:'approve'},'Approve').state;
  assert.equal(state.rehearsal.approved?.quantity,150);assert.equal(state.rehearsal.approved?.totalCents,195000);
  assert.equal(isCurrentPacket(state,packet),false);
});

test('company instruction survives a fresh session and changes the next decision',async()=>{
  const dir=await temporary();
  try{
    const store=new CompanyWorkspace(dir);
    const noted=applyIntent(newConversation('first'),{action:'remember',memoryNote:'Never split shipments.'},'Remember never to split shipments').state;
    await store.merge(noted);
    const reopened=await new CompanyWorkspace(dir).read();
    const fresh={...newConversation('second'),notes:reopened.notes};
    const reviewed=applyIntent(fresh,{action:'review',quantity:150},'150 shirts');
    assert.equal(reviewed.state.rehearsal.proposal?.chosen,null);
    const raised=applyIntent(reviewed.state,{action:'review',budgetDollars:2000},'Budget is 2000 dollars');
    assert.equal(raised.state.rehearsal.proposal?.chosen?.id,'express');
    await writeFile(resolve(dir,'memory.json'),'{broken');
    await assert.rejects(store.read());assert.equal(await readFile(resolve(dir,'memory.json'),'utf8'),'{broken');
  }finally{await rm(dir,{recursive:true,force:true});}
});

