test('another conversation changing policy or source invalidates both approval and draft eligibility',()=>{
  let state=applyIntent(newConversation('first'),{action:'review',quantity:150},'150 shirts').state;
  state.dataRevision='original';state=applyIntent(state,{action:'approve'},'Yes approve').state;
  const changed=refreshCompanyContext(state,'original',['Never split shipments.']);
  assert.equal(changed.rehearsal.approved,null);assert.equal(changed.rehearsal.proposal,null);
  assert.equal(applyIntent(changed,{action:'draft'},'Write the packet').draft,null);
  assert.equal(applyIntent(changed,{action:'approve'},'Yes approve').state.rehearsal.approved,null);
  const pricesChanged=refreshCompanyContext(state,'new-price-file',[]);
  assert.equal(pricesChanged.rehearsal.approved,null);assert.equal(pricesChanged.rehearsal.proposal,null);
  assert.equal(refreshCompanyContext(state,'original',[]).rehearsal.approved?.totalCents,175000);
});

