test('a failed Hotdata create is reconciled and only this run databases are deleted',async()=>{
  const dir=await temporary();
  const company=validateCompany(JSON.parse(await readFile('fixtures/company.json','utf8')));
  try{
    await writeFile(resolve(dir,'hotdata-allowance.json'),JSON.stringify({enabled:true,workspaceId:'worktest',freeCreditConfirmed:true,confirmedAvailableUsd:95,maxInputBytes:25000,validUntil:new Date(Date.now()+60000).toISOString(),maxRuns:1,proof:'isolated transport fault test; no API calls'}));
    const created:{id:string;name:string}[]=[],deleted:string[]=[];
    const fake=async(_workspace:string,method:string,path:string,body?:unknown):Promise<unknown>=>{
      const b=body as {name:string};
      if(method==='POST'&&path==='/v1/databases'){
        const db={id:'db-'+created.length,name:b.name};created.push(db);
        if(b.name.includes('shipping'))throw new Error('Create response lost after server write');return db;
      }
      if(method==='GET')return {databases:[...created,{id:'untouched',name:'Another company database'}],has_more:false};
      if(method==='DELETE'){deleted.push(path.split('/').at(-1)!);return null;}
      return {ok:true};
    };
    await assert.rejects(runDataWorkers(dir,company,[],'source',fake),/Create response lost/);
    assert.deepEqual(deleted.sort(),created.map(d=>d.id).sort());assert.ok(!deleted.includes('untouched'));
    assert.equal(JSON.parse(await readFile(resolve(dir,'hotdata-run-count.json'),'utf8')).used,1);
  }finally{await rm(dir,{recursive:true,force:true});}
});

test('repeating a prior instruction makes it current again after a contrary instruction',async()=>{
  const dir=await temporary();
  try{
    const store=new CompanyWorkspace(dir);let state=newConversation('repeat');
    for(const note of ['Never split shipments.','Allow split shipments.','Never split shipments.']){
      state.notes=(await store.read()).notes;
      state=applyIntent(state,{action:'remember',memoryNote:note},note).state;
      await store.merge(state);
    }
    const fresh={...newConversation('fresh'),notes:(await store.read()).notes};
    assert.equal(fresh.notes.at(-1),'Never split shipments.');
    assert.equal(applyIntent(fresh,{action:'review',quantity:150},'150 shirts').state.rehearsal.proposal?.chosen,null);
  }finally{await rm(dir,{recursive:true,force:true});}
});

test('newer retrieved Cognee memory restores an empty cache and cannot replace a later local revision',async()=>{
  const dir=await temporary();
  try{
    const store=new CompanyWorkspace(dir);
    const retained={schema:1 as const,revision:4,notes:['Never split shipments.'],approvals:[{conversationId:'past-conversation',quantity:150,totalCents:195000,option:'Express',at:new Date().toISOString()}],updatedAt:new Date().toISOString()};
    await store.restoreIfNewer(retained);
    const fresh={...newConversation('recovered'),notes:(await new CompanyWorkspace(dir).read()).notes};
    assert.equal(applyIntent(fresh,{action:'review',quantity:150},'150shirts').state.rehearsal.proposal?.chosen,null);
    await store.restoreIfNewer({...retained,revision:3,notes:['Allow split shipments.']});
    assert.deepEqual((await store.read()).notes,retained.notes);
  }finally{await rm(dir,{recursive:true,force:true});}
});

test('only a contradictory recognized shipment rule can make an instruction historical',()=>{
  const unrelated=['Never split shipments.','The customer asked about split sizes.'];
  assert.equal(shipmentPolicyInstruction(unrelated[1]),null);
  assert.equal(splitForbidden(unrelated),true);
  assert.deepEqual(historicalShipmentPolicyIndexes(unrelated),[]);
  const permitted=[...unrelated,'Allow split shipments.'];
  assert.equal(splitForbidden(permitted),false);
  assert.deepEqual(historicalShipmentPolicyIndexes(permitted),[0]);
  const forbidden=[...permitted,'Do not use split shipments.','Owner approval is required.'];
  assert.equal(splitForbidden(forbidden),true);
  assert.deepEqual(historicalShipmentPolicyIndexes(forbidden),[2]);
  assert.deepEqual(historicalShipmentPolicyIndexes(['Allow split shipments.','Split shipments are okay.']),[]);
});

test('live progress reflects actual pending work and an older run cannot overwrite a newer one',async()=>{
  const id='11111111-1111-4111-8111-111111111111';
  const first=beginProgress(id);let release!:()=>void;
  const task=first.run('hotdata','Query inventory',()=>new Promise<void>(resolve=>{release=resolve;}));
  const pending=progressSnapshot(id)!;assert.equal(pending.active,true);assert.equal(pending.steps[0].status,'running');assert.equal(pending.steps[0].finishedAt,undefined);
  pending.steps[0].task='tampered';assert.equal(progressSnapshot(id)!.steps[0].task,'Query inventory');
  release();await task;assert.equal(progressSnapshot(id)!.steps[0].status,'complete');assert.ok(progressSnapshot(id)!.steps[0].finishedAt);
  const second=beginProgress(id);const fresh=progressSnapshot(id)!;assert.notEqual(fresh.runId,pending.runId);assert.equal(fresh.steps.length,0);
  first.end();assert.equal(progressSnapshot(id)!.active,true);
  second.record('snapshot','hotdata','Reuse verified data','reused');second.end();
  assert.equal(progressSnapshot(id)!.active,false);assert.equal(progressSnapshot(id)!.steps[0].status,'reused');
  assert.equal(progressSnapshot('../private'),null);
});

test('live progress failure never turns unfinished work into success or exposes provider errors',async()=>{
  const id='22222222-2222-4222-8222-222222222222';const progress=beginProgress(id);
  progress.record('incomplete','hotdata','Query shipping','running');
  await assert.rejects(progress.run('rocketride','Verify proposal',async()=>{throw new Error('PRIVATE_PROVIDER_DETAIL');}));
  progress.end();const snapshot=progressSnapshot(id)!;
  assert.equal(snapshot.active,false);assert.equal(snapshot.steps.every(step=>step.status==='error'),true);
  assert.doesNotMatch(JSON.stringify(snapshot),/PRIVATE_PROVIDER_DETAIL/);
});

