// EXPORT-SPECIFIC CHECK — generated by export-judges.py for the exported server surface.
test('exported local server keeps its localhost, origin, CSP and static-file boundaries', async () => {
  const dir = await temporary();
  await writeFile(resolve(dir, 'index.html'), '<!doctype html><title>Redirect</title>');
  await writeFile(resolve(dir, 'talk.html'), '<!doctype html><title>Talk</title>');
  const server = makeServer({ storePath: resolve(dir, 'data/checklist.json'), publicPath: dir, monitor: false });
  await new Promise<void>(resolveListen => server.listen(0, '127.0.0.1', resolveListen));
  const address = server.address() as { port: number };
  const origin = `http://127.0.0.1:${address.port}`;
  try {
    assert.equal((await fetch(origin)).status, 200);
    const talk = await fetch(`${origin}/talk`);
    assert.equal(talk.status, 200);
    assert.match(talk.headers.get('content-security-policy')!, /frame-ancestors 'none'/);
    assert.match(talk.headers.get('content-security-policy')!, /media-src 'self' blob:/);
    assert.equal((await fetch(`${origin}/.env`)).status, 404);
    assert.equal((await fetch(`${origin}/evidence/unknown`)).status, 404);
    assert.equal((await fetch(`${origin}/api/tasks/anything`, { method: 'PATCH', headers: { Origin: origin, 'Content-Type': 'application/json' }, body: '{"revision":0,"edit":{"status":"active"}}' })).status, 404);
    assert.equal((await fetch(`${origin}/api/conversation/new`, { method: 'POST', headers: { Origin: 'https://outside.example', 'Content-Type': 'application/json' }, body: '{}' })).status, 403);
    const badHost = await new Promise<number | undefined>((resolveResponse, reject) => {
      const req = request(origin, { headers: { Host: 'outside.example' } }, res => { res.resume(); resolveResponse(res.statusCode); });
      req.on('error', reject); req.end();
    });
    assert.equal(badHost, 403);
    const company = await fetch(`${origin}/api/company`);
    assert.equal(company.status, 200);
    assert.equal((await company.json()).data.sampleData, true);
  } finally {
    const closed = new Promise<void>((resolveClose, reject) => server.close(error => error ? reject(error) : resolveClose()));
    server.closeAllConnections();
    await closed;
    await rm(dir, { recursive: true, force: true });
  }
});
